#include <iostream>
#include <algorithm>
using namespace std;

using i128 = __int128_t;

void print(i128 x) {
    if (x == 0) {
        cout << 0;
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s += char('0' + x % 10);
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    long long n;
    cin >> n;

    if (n <= 0) {
        cout << 0;
        return 0;
    }

    long long cnt[10] = {};
    for (int r = 1; r <= 9; ++r)
        cnt[r] = (n + 9 - r) / 9;

    i128 answer = 0;

    for (int a = 1; a <= 9; ++a) {
        for (int b = 1; b <= 9; ++b) {
            int productRoot = 1 + (a * b - 1) % 9;
            answer += (i128)cnt[a] * cnt[b] * cnt[productRoot];
        }
    }

    i128 excluded = 0;
    for (long long left = 1; left <= n;) {
        long long quotient = n / left;
        long long right = n / quotient;
        excluded += (i128)quotient * (right - left + 1);
        left = right + 1;
    }

    print(answer - excluded);
    return 0;
}

#include <iostream>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;

int main() {
    long long n;
    cin >> n;

    if (n <= 0) {
        cout << 0;
        return 0;
    }

    long long cnt[10] = {};
    for (int r = 1; r <= 9; ++r)
        cnt[r] = n / 9 + (n % 9 >= r);

    cpp_int answer = 0;
    for (int a = 1; a <= 9; ++a) {
        for (int b = 1; b <= 9; ++b) {
            int root = (a * b - 1) % 9 + 1;
            answer += cpp_int(cnt[a]) * cnt[b] * cnt[root];
        }
    }

    for (long long left = 1; left <= n;) {
        long long quotient = n / left;
        long long right = n / quotient;
        answer -= cpp_int(right - left + 1) * quotient;
        if (right == n) break;
        left = right + 1;
    }

    cout << answer;
    return 0;
}

