    long long n;
    cin >> n;

    long long count[10] = {};
    for (int root = 1; root <= 9; ++root)
        count[root] = (n + 9 - root) / 9;

    __int128 answer = 0;

    for (int a = 1; a <= 9; ++a) {
        for (int b = 1; b <= 9; ++b) {
            int root = (a * b - 1) % 9 + 1;
            answer += (__int128)count[a] * count[b] * count[root];
        }
