#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    int64 cnt[10] = {};
    for (int r = 1; r <= 9; ++r)
        cnt[r] = (n + 9 - r) / 9;

    i128 result = 0;

    for (int a = 1; a <= 9; ++a) {
        for (int b = 1; b <= 9; ++b) {
            int root = (a * b - 1) % 9 + 1;
            result += (i128)cnt[a] * cnt[b] * cnt[root];
        }
    }

    i128 excluded = 0;
    for (int64 l = 1, r; l <= n; l = r + 1) {
        int64 q = n / l;
        r = n / q;
        excluded += (i128)(r - l + 1) * q;
    }

    result -= excluded;

    if (result == 0) {
        cout << 0;
        return 0;
    }

    string output;
    while (result > 0) {
        output += char('0' + result % 10);
        result /= 10;
    }

    reverse(output.begin(), output.end());
    cout << output;

    return 0;
}

